import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"EmakiSkills","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/skills/index.md","filePath":"en/modules/skills/index.md","lastUpdated":0}`),a={name:`en/modules/skills/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="emakiskills" tabindex="-1">EmakiSkills <a class="header-anchor" href="#emakiskills" aria-label="Permalink to “EmakiSkills”">​</a></h1><p>EmakiSkills manages skill unlocks, active slots, passive triggers, cast mode, cooldowns, resources, upgrades, and player profiles — that is, when a cast is allowed, what it costs, and who triggers it.</p><p>Skill effects themselves run through one of two paths, selected by <code>script.mode</code>: <code>native</code> uses the built-in script system (<code>script_engine.default_mode</code> is <code>native</code> by default and needs no external plugin), <code>mythic</code> hands execution to MythicMobs, and <code>hybrid</code> runs both.</p><h2 id="module-facts" tabindex="-1">Module facts <a class="header-anchor" href="#module-facts" aria-label="Permalink to “Module facts”">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Module version</td><td><code>2.8.1</code></td></tr><tr><td>Jar name</td><td><code>EmakiSkills-2.8.1.jar</code></td></tr><tr><td>Maven coordinate</td><td><code>emaki.jiuwu.craft:emaki-skills:2.8.1</code></td></tr><tr><td>API coordinate</td><td><code>emaki.jiuwu.craft:emaki-skills-api:2.8.1</code></td></tr><tr><td>Platform</td><td>Paper <code>1.21.8</code> (<code>api-version: &quot;1.21.8&quot;</code>, <code>folia-supported: true</code>)</td></tr><tr><td>Main command</td><td><code>/emakiskills</code></td></tr><tr><td>Alias</td><td><code>/eskills</code></td></tr><tr><td>Hard dependency</td><td>EmakiCoreLib</td></tr><tr><td>Soft dependencies</td><td>MythicMobs, EmakiAttribute, PlaceholderAPI, AuraSkills, MythicLib, MMOCore</td></tr><tr><td>Main permissions</td><td><code>emakiskills.use</code>, <code>emakiskills.reload</code>, <code>emakiskills.admin</code>, <code>emakiskills.debug</code></td></tr></tbody></table><h2 id="module-split" tabindex="-1">Module split <a class="header-anchor" href="#module-split" aria-label="Permalink to “Module split”">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Responsibility</th></tr></thead><tbody><tr><td>EmakiSkills</td><td>Skill definitions, slots, triggers, cooldowns, resources, upgrades, and player data.</td></tr><tr><td>MythicMobs</td><td>Executes the actual skill effects such as damage, particles, summons, and movement.</td></tr><tr><td>EmakiAttribute</td><td>Provides attribute checks, resource checks, and resource consumption.</td></tr><tr><td>EmakiItem</td><td>Items may provide skill unlocks, triggers, or set skills.</td></tr><tr><td>PlaceholderAPI</td><td>Displays skill state, cooldowns, levels, and more.</td></tr></tbody></table><h2 id="default-runtime-folder" tabindex="-1">Default runtime folder <a class="header-anchor" href="#default-runtime-folder" aria-label="Permalink to “Default runtime folder”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>plugins/EmakiSkills/</span></span>
<span class="line"><span>├── config.yml</span></span>
<span class="line"><span>├── skills/</span></span>
<span class="line"><span>├── resources/</span></span>
<span class="line"><span>├── gui/</span></span>
<span class="line"><span>│   ├── skills_gui.yml</span></span>
<span class="line"><span>│   ├── trigger_select_gui.yml</span></span>
<span class="line"><span>│   └── upgrade_gui.yml</span></span>
<span class="line"><span>├── data/</span></span>
<span class="line"><span>└── lang/</span></span></code></pre></div><h2 id="top-level-config-yml-keys" tabindex="-1">Top-level config.yml keys <a class="header-anchor" href="#top-level-config-yml-keys" aria-label="Permalink to “Top-level config.yml keys”">​</a></h2><p><code>config.yml</code> only holds the version, language, default-data release switch, and the <code>slots</code> block at the top level. The remaining keys belong to the feature pages.</p><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># version is maintained by resource syncing and is not a feature switch.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">version</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.8.1&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Language file name, resolved as lang/&lt;language&gt;.yml.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">language</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;zh_CN&quot;</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;"># Whether to release the plugin&#39;s bundled default skill data at startup.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">release_default_data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">slots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">  # Default skill slot count; values below 1 are treated as 1.</span></span>
<span class="line"><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">  default_count</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Default</th><th>Values</th><th>Description</th></tr></thead><tbody><tr><td><code>version</code></td><td>string</td><td>No</td><td><code>&quot;2.8.1&quot;</code></td><td>—</td><td>Resource version, maintained by the resource sync flow; it is not a feature switch.</td></tr><tr><td><code>language</code></td><td>string</td><td>No</td><td><code>&quot;zh_CN&quot;</code></td><td>A file name under <code>lang/</code> without <code>.yml</code></td><td>Loads <code>lang/&lt;language&gt;.yml</code> as the source of player-visible text.</td></tr><tr><td><code>release_default_data</code></td><td>boolean</td><td>No</td><td><code>true</code></td><td><code>true</code> / <code>false</code></td><td>Whether bundled default skill data (example skills and so on) is released at startup.</td></tr><tr><td><code>slots.default_count</code></td><td>integer</td><td>No</td><td><code>3</code></td><td>≥ 1, values below 1 become 1</td><td>Default skill slot count per player; drives the <code>%slot_1%</code>~<code>%slot_n%</code> range in the action bar and the baseline for <code>%emakiskills_slot_count%</code>.</td></tr></tbody></table><p>Where the other keys live:</p><table tabindex="0"><thead><tr><th>Keys</th><th>Documented on</th></tr></thead><tbody><tr><td><code>skill_sources.*</code>, <code>skill_tags.equip_limits</code></td><td><a href="./definitions.html">Definitions</a></td></tr><tr><td><code>triggers</code>, <code>passive_triggers</code>, <code>trigger_settings</code>, <code>passive_trigger_settings</code>, <code>cast_mode</code></td><td><a href="./triggers.html">Triggers</a></td></tr><tr><td><code>actionbar</code>, <code>cast_timing</code></td><td><a href="./actionbar.html">Action bar</a></td></tr><tr><td><code>script_engine</code></td><td><a href="./script.html">Native scripting</a></td></tr></tbody></table><div class="note custom-block"><p class="custom-block-title">Config precheck</p><p>Loading checks that <code>config.yml</code>, <code>skills/</code>, <code>resources/</code>, and <code>gui/</code> exist and parse, and compiles script action lines to report diagnostics. A warning is raised when both <code>skill_sources</code> sides are off, or when <code>require_lore_pdc_match</code> is on with only one side enabled.</p></div><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to “Pages”">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Content</th></tr></thead><tbody><tr><td><a href="./commands.html">Commands</a></td><td>GUI, cast mode, level management, slot cleanup, and debug commands.</td></tr><tr><td><a href="./definitions.html">Definitions</a></td><td>Active/passive skills, resource consumption, upgrades, and config fields.</td></tr><tr><td><a href="./triggers.html">Triggers</a></td><td>Active triggers, passive triggers, conflicts, and combo configuration.</td></tr><tr><td><a href="./parameters.html">Variable types</a></td><td>Variable types, fields, and runtime resolution.</td></tr><tr><td><a href="./script.html">Native scripting</a></td><td>Script modes, stages, actions, limits, and target resolution.</td></tr><tr><td><a href="./actionbar.html">Action bar</a></td><td>Action bar templates, refresh intervals, and cast mode hints.</td></tr><tr><td><a href="./placeholders.html">Placeholders</a></td><td>PlaceholderAPI output.</td></tr><tr><td><a href="./corelib-actions.html">CoreLib Actions</a></td><td>Skill cast, level, slot, cooldown, and manual unlock actions.</td></tr><tr><td><a href="./api.html">API</a></td><td>Skill API and external skill-source extensions.</td></tr><tr><td><a href="./events.html">Event API</a></td><td>Bukkit events and interception points across the skill flow.</td></tr></tbody></table><h2 id="skill-types" tabindex="-1">Skill types <a class="header-anchor" href="#skill-types" aria-label="Permalink to “Skill types”">​</a></h2><h3 id="active-skills" tabindex="-1">Active skills <a class="header-anchor" href="#active-skills" aria-label="Permalink to “Active skills”">​</a></h3><p>Active skills are usually cast manually by the player through a skill slot, command, GUI, or cast mode. Common configuration includes:</p><ul><li>MythicMobs skill ID.</li><li>Cooldown.</li><li>Global cooldown.</li><li>Resource consumption.</li><li>Condition checks.</li><li>Skill level and parameters.</li></ul><h3 id="passive-skills" tabindex="-1">Passive skills <a class="header-anchor" href="#passive-skills" aria-label="Permalink to “Passive skills”">​</a></h3><p>Passive skills are triggered by events such as attack, being hit, kill, movement, or block. Passive skills need trigger and conflict handling settings.</p><h2 id="cast-mode" tabindex="-1">Cast mode <a class="header-anchor" href="#cast-mode" aria-label="Permalink to “Cast mode”">​</a></h2><p>Cast mode lets the player select or cast skills under certain states. Because the client-side G key cannot be observed natively by the server, skill triggers usually rely on server-visible behavior such as commands, GUI, F key item swap, or interaction events.</p><h2 id="resource-system" tabindex="-1">Resource system <a class="header-anchor" href="#resource-system" aria-label="Permalink to “Resource system”">​</a></h2><p>Skills can consume or check multiple kinds of resources:</p><ul><li><code>ea-resource</code>: consume Attribute resources through the EmakiAttribute bridge.</li><li><code>attribute-check</code>: verify a certain attribute meets the requirement. Alias: <code>ea-attribute-check</code>.</li><li><code>local-resource</code>: use EmakiSkills&#39; local resource definitions.</li><li><code>auraskills-mana</code>: use AuraSkills mana. Aliases: <code>aura-skills-mana</code>, <code>aura-mana</code>.</li><li><code>mythiclib-mana</code>: use MythicLib / MMOCore mana. Aliases: <code>mmocore-mana</code>, <code>mythic-mana</code>.</li></ul><h2 id="typical-cast-flow" tabindex="-1">Typical cast flow <a class="header-anchor" href="#typical-cast-flow" aria-label="Permalink to “Typical cast flow”">​</a></h2><ol><li>The player triggers an active or passive skill.</li><li>Skills checks whether the player owns the skill.</li><li>Skills checks skill level, slot, trigger, and conditions.</li><li>Skills checks cooldown and global cooldown.</li><li>Skills checks and consumes resources.</li><li>Skills runs the built-in script actions, the MythicMobs skill, or both, according to <code>script.mode</code>.</li><li>Skills writes cooldown, statistics, or upgrade progress.</li><li>Skills sends feedback to the player.</li></ol><p>Player-visible failure feedback comes from <code>lang/&lt;language&gt;.yml</code> keys such as <code>cast.*</code>; internal reason keys are never shown to players.</p>`,32)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};